using System.Security.Claims;using Indamin.Performance.Data;using Indamin.Performance.Services;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace Indamin.Performance.Controllers;
[Authorize]public class EmployeeDashboardController(AppDbContext db):Controller{
public async Task<IActionResult>Index(int? periodId){if(!int.TryParse(User.FindFirstValue("EmployeeId"),out var id))return Forbid();var e=await db.Employees.AsNoTracking().Include(x=>x.Position).Include(x=>x.Unit).SingleOrDefaultAsync(x=>x.Id==id&&x.IsActive);if(e==null)return Forbid();var periods=await db.Periods.AsNoTracking().OrderByDescending(x=>x.StartAt).ToListAsync();var evs=await db.Evaluations.AsNoTracking().Where(x=>x.EmployeeId==id).Include(x=>x.Period).Include(x=>x.Scores).ToListAsync();var rows=evs.OrderByDescending(x=>x.Period!.StartAt).Select(x=>new EvaluationSummaryVm(x.PeriodId,x.Period!.Title,PerformanceService.ToJalali(x.Period.StartAt),x.FinalScore,x.FinalMaxScore,x.Status.ToString())).ToList();var selected=periodId.HasValue?rows.FirstOrDefault(x=>x.PeriodId==periodId):rows.FirstOrDefault();var questionIds=evs.SelectMany(x=>x.Scores).Select(x=>x.QuestionId).Distinct().ToList();var qmap=await db.Questions.AsNoTracking().Where(x=>questionIds.Contains(x.Id)).ToDictionaryAsync(x=>x.Id);var selectedEv=selected==null?null:evs.FirstOrDefault(x=>x.PeriodId==selected.PeriodId);var detail=selectedEv==null?null:BuildDetail(selectedEv,qmap);var trend=rows.AsEnumerable().Reverse().Select(x=>new TrendVm(x.Title,x.Percentage)).ToList();var qtrend=selectedEv==null?[]:BuildQuestionTrend(selectedEv,qmap);var strengths=selectedEv==null?[]:BuildAreas(selectedEv,qmap,true);var improvements=selectedEv==null?[]:BuildAreas(selectedEv,qmap,false);return View(new DashboardVm(e.FullName,e.PersonnelNo,e.Position?.Title??"—",e.Unit?.Title??"—",rows,periods.Select(x=>new PeriodOptionVm(x.Id,x.Title,rows.Any(r=>r.PeriodId==x.Id))).ToList(),selected?.PeriodId,detail,trend,qtrend,strengths,improvements));}
static DetailVm BuildDetail(Evaluation e,Dictionary<int,Question> qmap){var items=e.Scores.OrderBy(x=>x.QuestionId).Select(s=>{var q=qmap.GetValueOrDefault(s.QuestionId);var label=q==null?"سؤال "+s.QuestionId:$"{q.Code} - {q.Title}";return new QuestionScoreVm(label,s.Score,s.MaxScore,s.MaxScore>0?Math.Round(s.Score*100/s.MaxScore,1):0,s.Comment);}).ToList();var max=e.FinalMaxScore>0?e.FinalMaxScore:items.Sum(x=>x.MaxScore);var total=e.FinalScore;return new DetailVm(e.Period!.Title,PerformanceService.ToJalali(e.Period.StartAt),total,max,max>0?Math.Round(total*100/max,1):0,items);}
static List<TrendVm>BuildQuestionTrend(Evaluation e,Dictionary<int,Question> qmap)=>e.Scores.Select(s=>{var q=qmap.GetValueOrDefault(s.QuestionId);return new TrendVm(q==null?"سؤال "+s.QuestionId:$"{q.Code} - {q.Title}",s.MaxScore>0?Math.Round(s.Score*100/s.MaxScore,1):0);}).OrderByDescending(x=>x.Percentage).ToList();
static List<AreaVm>BuildAreas(Evaluation e,Dictionary<int,Question> qmap,bool strong)=>e.Scores.Select(s=>{var q=qmap.GetValueOrDefault(s.QuestionId);return new AreaVm(q==null?"سؤال "+s.QuestionId:$"{q.Code} - {q.Title}",s.MaxScore>0?Math.Round(s.Score*100/s.MaxScore,1):0);}).Where(x=>strong?x.Percentage>=80:x.Percentage<60).OrderByDescending(x=>strong?x.Percentage:-x.Percentage).Take(5).ToList();
public record DashboardVm(string Name,string PersonnelNo,string Position,string Unit,List<EvaluationSummaryVm> Evaluations,List<PeriodOptionVm> Periods,int? SelectedPeriodId,DetailVm? SelectedDetail,List<TrendVm> Trend,List<TrendVm> QuestionTrend,List<AreaVm> Strengths,List<AreaVm> Improvements);public record EvaluationSummaryVm(int PeriodId,string Title,string Date,decimal Score,decimal MaxScore,string Status){public decimal Percentage=>MaxScore==0?0:Math.Round(Score*100/MaxScore,1);}public record PeriodOptionVm(int Id,string Title,bool HasEvaluation);public record DetailVm(string Title,string Date,decimal Score,decimal MaxScore,decimal Percentage,List<QuestionScoreVm> Questions);public record QuestionScoreVm(string Text,decimal Score,decimal MaxScore,decimal Percentage,string? Comment);public record TrendVm(string Label,decimal Percentage);public record AreaVm(string Label,decimal Percentage);
}